using UnityEngine;
using UnityEngine.Rendering;

[System.Serializable]
public class SurfaceTextureSet
{
    public SurfaceTexture type;
    public Texture2D albedo;
    public Texture2D normal;
    public Texture2D emission;
    [Tooltip("u wraps around the circle, v runs outward (for raked gravel / sand ripples).")]
    public bool polarUV;
}

/// <summary>
/// Shared assets for all recipe-based environments: material templates (which also keep the needed shader
/// variants in the build), tintable surface textures and reusable prop meshes.
/// Generated by Tools > Last Brick > Environments > Build All 100 Environments.
/// </summary>
public class EnvironmentLibrary : ScriptableObject
{
    [Header("Material Templates")]
    public Material litPlain;
    public Material litTexture;
    public Material litTextureNormal;
    public Material litTextureNormalEmissive;
    public Material litEmissive;
    public Material vertexColorLit;
    public Material particleAdditive;
    public Material particleAlpha;
    public Material sky;
    [Tooltip("Not used directly - keeps the post-processing shader variants in the build.")]
    public VolumeProfile postProcessTemplate;

    [Header("Surfaces")]
    public SurfaceTextureSet[] surfaces;

    [Header("Particle Textures")]
    public Texture2D softDot;
    public Texture2D petal;

    [Header("Prop Meshes")]
    public Mesh limb;
    public Mesh cylinder;
    public Mesh hexCylinder;
    public Mesh cone;
    public Mesh hexCone;
    public Mesh pyramid;
    public Mesh squareFrustum;
    public Mesh box;
    public Mesh tinyBlob;
    public Mesh cloudBlob;
    public Mesh flatCanopy;
    public Mesh frond;
    public Mesh mushroomCap;
    public Mesh flutedShaft;
    public Mesh[] canopyBlobs;
    public Mesh[] pineTiers;
    public Mesh[] rocks;

    public SurfaceTextureSet GetSurface(SurfaceTexture type)
    {
        if (surfaces == null) return null;
        foreach (SurfaceTextureSet s in surfaces)
        {
            if (s != null && s.type == type) return s;
        }
        return null;
    }
}
